// src/pages/Mesas.jsx
import { useEffect, useState } from "react";
import { getMesas, api } from "../services/api";
import { Table, Users, Clock } from "lucide-react";
import "./Mesas.css";

const ESTADOS = {
  libre: { color: "#10b981", nombre: "Libre", icon: Table },
  ocupada: { color: "#e74c3c", nombre: "Ocupada", icon: Users },
  reservada: { color: "#f59e0b", nombre: "Reservada", icon: Clock }
};

export default function Mesas() {
  const [mesas, setMesas] = useState([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    cargarMesas();
  }, []);

  const cargarMesas = async () => {
    try {
      const data = await getMesas();
      setMesas(data);
    } catch (err) {
      alert("Error cargando mesas");
    } finally {
      setLoading(false);
    }
  };

  const cambiarEstado = async (id, estadoActual) => {
    const nuevosEstados = ["libre", "ocupada", "reservada"];
    const indiceActual = nuevosEstados.indexOf(estadoActual);
    const nuevoEstado = nuevosEstados[(indiceActual + 1) % 3];

    try {
      await api.put(`/api/mesas/${id}/`, { estado: nuevoEstado });
      setMesas(prev => prev.map(m => 
        m.id === id ? { ...m, estado: nuevoEstado } : m
      ));
    } catch (err) {
      alert("Error al cambiar estado");
    }
  };

  if (loading) return <div className="loader">Cargando mesas...</div>;

  return (
    <div className="mesas-page">
      <div className="mesas-bg"></div>
      <div className="mesas-overlay"></div>

      <div className="mesas-content">
        <h1 className="mesas-title">CONTROL DE MESAS</h1>
        <p className="mesas-subtitle">Haz click en cualquier mesa para cambiar su estado</p>

        <div className="mesas-grid">
          {mesas.map((mesa) => {
            const estado = ESTADOS[mesa.estado] || ESTADOS.libre;
            const Icon = estado.icon;

            return (
              <div
                key={mesa.id}
                className="mesa-card"
                onClick={() => cambiarEstado(mesa.id, mesa.estado)}
                style={{ "--estado-color": estado.color }}
              >
                <div className="mesa-header">
                  <Icon size={40} />
                  <span className="mesa-numero">Mesa {mesa.numero}</span>
                </div>

                <div className="mesa-body">
                  <div className="estado-badge">
                    <div className="punto"></div>
                    <span>{estado.nombre}</span>
                  </div>
                  <p>Capacidad: {mesa.capacidad} personas</p>
                </div>

                <div className="mesa-glow"></div>
              </div>
            );
          })}
        </div>

        <div className="leyenda">
          <div><span style={{background: "#10b981"}}></span> Libre</div>
          <div><span style={{background: "#e74c3c"}}></span> Ocupada</div>
          <div><span style={{background: "#f59e0b"}}></span> Reservada</div>
        </div>
      </div>
    </div>
  );
}
